begin;
do $$
declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();b uuid:=gen_random_uuid();w uuid;other uuid;obj uuid;people uuid;rec uuid;won uuid;p uuid;i uuid;second_account uuid;mail uuid;private_note uuid;r jsonb;batch jsonb;q jsonb:='[{"kind":"record","metric":"count"},{"metric":"count","kind":"record"}]';
begin
 insert into auth.users(id,email) values(u,'perf-owner@example.test'),(v,'perf-viewer@example.test'),(b,'perf-other@example.test');
 perform set_config('request.jwt.claim.sub',u::text,true);
 w:=public.create_workspace('Aggregate A');
 select id into obj from public.objects where workspace_id=w and slug='deals';
 select id into people from public.objects where workspace_id=w and slug='people';
 select id into p from public.pipelines where workspace_id=w limit 1;
 insert into public.memberships(workspace_id,user_id,role,display_name) values(w,v,'member','Private sources owner');
 insert into public.records(workspace_id,object_id,display_name,stage,amount,probability,owner_id,pipeline_id,created_at)
 values(w,obj,'Open deal','Qualification',125.05,33.3,u,p,now()-interval '20 days') returning id into rec;
 insert into public.records(workspace_id,object_id,display_name,stage,amount,owner_id,pipeline_id) values(w,obj,'Reopened deal','Gagné',300,u,p) returning id into won;
 update public.records set stage='Proposition' where id=won;
 update public.records set stage='Perdu',lost_reason='Too expensive' where id=won;
 update public.records set stage='Qualification' where id=won;
 update public.records set stage='Gagné' where id=won;
 insert into public.records(workspace_id,object_id,display_name,created_at) select w,people,'Priority '||n,now()-interval '20 days' from generate_series(1,101) n;
 insert into public.tasks(workspace_id,record_id,title,owner_id,due_date) values(w,rec,'Overdue',u,now()-interval '1 day'),(w,rec,'Future',u,now()+interval '1 day');
 insert into public.commitments(workspace_id,record_id,title,owner_id,due_date,status) values(w,rec,'Promise',u,now()-interval '1 day','confirmed');
 insert into public.commitments(workspace_id,record_id,title,owner_id,due_date,status,private,author_id) values(w,rec,'Private promise',v,now()-interval '1 day','confirmed',true,v);
 insert into public.conflicts(workspace_id,record_id,title,field,source_a,source_b) values(w,rec,'Conflict','stage','{}','{}');
 insert into public.notes(workspace_id,record_id,title,content,private,author_id) values(w,rec,'Private source','SECRET_NOT_VISIBLE',true,v) returning id into private_note;
 insert into public.integrations(workspace_id,user_id,provider,email,status) values(w,u,'gmail','perf-owner@example.test','connected') returning id into i;
 insert into public.integrations(workspace_id,user_id,provider,email,status) values(w,u,'outlook','perf-outlook@example.test','connected') returning id into second_account;
 insert into public.communications(workspace_id,user_id,integration_id,provider_id,kind,direction,thread_id,record_id,received_at)
 values(w,u,i,'inbound','email','inbound','thread',rec,now()-interval '1 hour') returning id into mail;
 insert into public.communications(workspace_id,user_id,integration_id,provider_id,kind,direction,thread_id,record_id,received_at)
 values(w,u,second_account,'other-account','email','outbound','thread',rec,now());
 perform set_config('request.jwt.claim.sub',b::text,true);other:=public.create_workspace('Aggregate B');
 perform set_config('request.jwt.claim.sub',u::text,true);
 execute 'set local role authenticated';
 r:=public.crm_sales_report(w);
 if (r->>'total')::integer<>2 or (r->'forecast'->'EUR'->>'weighted')::numeric<>41.64 or (r->'forecast'->'EUR'->>'won')::numeric<>300 then raise exception 'Report counts or per-deal weighted rounding changed %',r;end if;
 if (r->'history'->'outcomes'->'EUR'->>'wonCount')::integer<>1 or (r->'history'->'outcomes'->'EUR'->>'undated')::integer<>0 then raise exception 'Audited reopening outcome incorrect %',r;end if;
 if not exists(select 1 from jsonb_array_elements(r->'history'->'calibration') c where c->>'stage'='Proposition' and (c->>'resolved')::integer=1 and (c->>'won')::integer=1) then raise exception 'Observed-stage calibration lost reopening history';end if;
 r:=public.crm_priorities(w);
 if jsonb_array_length(r->'data')<>50 or (r->>'total')::integer<>103 or (r->>'next_offset')::integer<>50 or (r->'data'->0->>'score')::integer<>90 then raise exception 'Priorities scoring, privacy or pagination changed %',r;end if;
 if (public.crm_priorities(w,u)->>'total')::integer<>2 then raise exception 'Owner filter applied after pagination';end if;
 r:=public.crm_record_context(w,rec,'summary');
 if (r->'counts'->>'notes')::integer<>0 or r::text like '%SECRET_NOT_VISIBLE%' or jsonb_array_length(r->'timeline')>13 then raise exception 'Summary leaked private source or unbounded content';end if;
 r:=public.crm_record_context(w,rec,'timeline');
 if r::text like '%SECRET_NOT_VISIBLE%' or (r->'counts'->>'commitments')::integer<>1 then raise exception 'Timeline private source leak';end if;
 r:=public.crm_pulse(w);
 if (r->'counts'->>'opportunities')::integer<>2 or (r->'counts'->>'attention')::integer<>3 or r->'signals'->0->>'source_id'<>mail::text then raise exception 'Pulse count or exact account/thread reply check changed %',r;end if;
 batch:=public.dashboard_batch(w,q);
 if batch->0 is distinct from batch->1 or (batch->0->'result'->>'total')::integer<>103 then raise exception 'Batch deduplication failed';end if;
 execute 'reset role';
 if ((select count(*) from relay_private.crm_aggregate_cache where workspace_id=w)+(select count(*) from relay_private.crm_record_aggregate_cache where workspace_id=w))<>1 then raise exception 'Equivalent requests not cached once';end if;
 update public.records set archived=true where id=won;
 execute 'set local role authenticated';
 if (public.dashboard_batch(w,q)->0->'result'->>'total')::integer<>102 then raise exception 'Cache survived data mutation';end if;
 begin perform public.crm_sales_report(other);raise exception 'Report workspace leak';exception when insufficient_privilege then null;end;
 begin perform public.crm_priorities(other);raise exception 'Priorities workspace leak';exception when insufficient_privilege then null;end;
 begin perform public.crm_pulse(other);raise exception 'Pulse workspace leak';exception when insufficient_privilege then null;end;
 begin perform public.dashboard_batch(other,q);raise exception 'Cache workspace leak';exception when insufficient_privilege then null;end;
 execute 'reset role';
 update public.memberships set role='viewer' where workspace_id=w and user_id=v;
 insert into relay_private.reader_record_access(workspace_id,user_id,record_id) values(w,v,rec);
 perform set_config('request.jwt.claim.sub',v::text,true);
 execute 'set local role authenticated';
 if (public.dashboard_batch(w,q)->0->'result'->>'total')::integer<>1 then raise exception 'Owner aggregate cache leaked to restricted reader';end if;
 if (public.crm_sales_report(w)->>'total')::integer<>1 or (public.crm_priorities(w)->>'total')::integer<>1 then raise exception 'Report or priorities bypassed restricted reader RLS';end if;
 if (public.crm_pulse(w)->'counts'->>'opportunities')::integer<>1 then raise exception 'Pulse bypassed restricted reader RLS';end if;
 execute 'reset role';
 delete from relay_private.reader_record_access where workspace_id=w and user_id=v;
 execute 'set local role authenticated';
 if (public.dashboard_batch(w,q)->0->'result'->>'total')::integer<>0 then raise exception 'Cache survived fine-grained grant revocation';end if;
 execute 'reset role';
 update public.commitments set owner_id=null where workspace_id=w and owner_id=v;
 delete from public.memberships where workspace_id=w and user_id=v;
 execute 'set local role authenticated';
 begin perform public.dashboard_batch(w,q);raise exception 'Cache survived membership revocation';exception when insufficient_privilege then null;end;
 raise notice 'Aggregate reads: exact forecast/history, paged scoring, source privacy, account/thread matching, cache invalidation, workspace and grant revocation passed';
end $$;
rollback;
